const tabId = 2052873101;
const details = await browserjs(tabId, () => {
  const tasty = document.querySelector('.tasty-recipes') || document.querySelector('.tasty-recipe');
  const ingredients = Array.from(document.querySelectorAll('.tasty-recipes-ingredients li, .tasty-recipe-ingredients li')).map(li => li.innerText.trim());
  const instructions = Array.from(document.querySelectorAll('.tasty-recipes-instructions li, .tasty-recipe-instructions li')).map(li => li.innerText.trim());
  const cookTime = document.querySelector('.tasty-recipes-cook-time')?.innerText?.trim();
  const prepTime = document.querySelector('.tasty-recipes-prep-time')?.innerText?.trim();
  const totalTime = document.querySelector('.tasty-recipes-total-time')?.innerText?.trim();

  // Also get the text from the sections: "The Best Lentils for Instant Pot Cooking", "My Water to Lentil Ratio"
  const sections = {};
  const h2Elements = Array.from(document.querySelectorAll('h2'));
  for (const h2 of h2Elements) {
    const title = h2.innerText.trim();
    let text = '';
    let next = h2.nextElementSibling;
    while (next && next.tagName !== 'H2') {
      text += next.innerText + '\n';
      next = next.nextElementSibling;
    }
    sections[title] = text.trim();
  }

  return {
    ingredients,
    instructions,
    cookTime,
    prepTime,
    totalTime,
    sections: {
      "The Best Lentils for Instant Pot Cooking": sections["The Best Lentils for Instant Pot Cooking"],
      "My Water to Lentil Ratio": sections["My Water to Lentil Ratio"],
      "How to Cook Lentils in a Pressure Cooker": sections["How to Cook Lentils in a Pressure Cooker"]
    }
  };
});

console.log(JSON.stringify(details, null, 2));

