  const h2s = Array.from(document.querySelectorAll('h2'));
  const targetH2 = h2s.find(h => h.innerText.includes("customize"));
  if (!targetH2) return null;
  let text = '';
  let next = targetH2.nextElementSibling;
  while (next && next.tagName !== 'H2') {
    text += next.innerText + '\n';
    next = next.nextElementSibling;
  }
  return text.trim();
});
