const tabId = 2052873140;
const recipes = await browserjs(tabId, async () => {
  const urls = [
    "https://www.ambitiouskitchen.com/seriously-the-best-healthy-turkey-chili/",
    "https://www.ambitiouskitchen.com/slow-cooker-black-bean-pumpkin-turkey-chili/",
    "https://www.ambitiouskitchen.com/two-bean-corn-chipotle-turkey-chili-healthy/",
    "https://www.ambitiouskitchen.com/chipotle-turkey-quinoa-chili/"
