await tool.wait_for({ tabId, condition: "load_state", value: "load" });

// Now let's fetch searches for chia pudding and pecan bars from Feel Good Foodie
const searches = await browserjs(tabId, async () => {
  const fetchResults = async (q) => {
    const resp = await fetch("https://feelgoodfoodie.net/?s=" + encodeURIComponent(q));
    const html = await resp.text();
    const doc = new DOMParser().parseFromString(html, "text/html");
    return Array.from(doc.querySelectorAll('article, .post-item, .entry-title a, h2 a, [class*="post"] a')).map(el => {
      const a = el.tagName === 'A' ? el : el.querySelector('a');
      return {
        title: a?.innerText?.trim(),
        url: a?.href
      };
    }).filter(x => x.title && x.url && x.url.includes("feelgoodfoodie.net/recipe/") && !x.url.includes("/category/"));
  };

  const chia = await fetchResults("chia pudding");
  const pecan = await fetchResults("pecan bars");

  return { chia: chia.slice(0, 5), pecan: pecan.slice(0, 5) };
});

console.log("Chia pudding candidates:", searches.chia);
console.log("Pecan bars candidates:", searches.pecan);

